import { defineStore } from 'pinia';
import type { CustomRuleScope } from 'src/services/settings/CustomValidationRulesApiService';

export type CvrScopeFilter = 'all' | CustomRuleScope;
export type CvrStatusFilter = 'all' | 'active' | 'inactive';

export interface CvrListFilters {
  search: string;
  scopeFilter: CvrScopeFilter;
  statusFilter: CvrStatusFilter;
}

function emptyFilters(): CvrListFilters {
  return { search: '', scopeFilter: 'all', statusFilter: 'all' };
}

// In-memory toolbar filter state for the Custom Validation Rules list, so the
// search box and scope/status toggles survive navigating into a rule and back.
// Scoped to one doc type — switching doc type starts from a clean slate.
export const useCvrListFiltersStore = defineStore('cvr_list_filters', {
  state: () => ({
    docTypeKey: '',
    filters: emptyFilters(),
  }),

  actions: {
    filtersFor(docTypeKey: string): CvrListFilters {
      if (this.docTypeKey !== docTypeKey) {
        this.docTypeKey = docTypeKey;
        this.filters = emptyFilters();
      }
      return this.filters;
    },

    setFilters(docTypeKey: string, filters: CvrListFilters) {
      this.docTypeKey = docTypeKey;
      this.filters = { ...filters };
    },
  },
});
