<template>
  <div class="page-container custom-validation-rules-page">
    <!-- Intro + doc type. Same block as the transformation-rules list. -->
    <div class="page-head">
      <div class="page-intro">
        <h3 class="fb-title page-intro__title">
          {{ $t('custom_validation_rules') }}
          <q-tooltip anchor="top middle" self="bottom middle" :offset="[0, 6]">
            {{ $t('custom_validation_rules') }}
          </q-tooltip>
        </h3>
        <p class="page-intro__subtitle page-intro__subtitle--md">
          {{ $t('custom_validation_rules_description') }}
        </p>
      </div>

      <div v-if="doc_type_key" class="page-doctype">
        <Icon icon="mdi:file-document-outline" class="page-doctype__icon" />
        <span class="page-doctype__label">{{ $t('document_type') }}</span>
        <span class="page-doctype__value" data-test="doc-type">{{ doc_type_key }}</span>
      </div>
    </div>

    <!-- Toolbar — search sits top-left; the scope + status toggles and the
         New Rule action are pushed to the right (app-wide list pattern). -->
    <div class="flex items-center gap-2 q-mb-md">
      <q-input
        class="list-search"
        outlined dense
        debounce="300"
        color="primary"
        v-model="search"
        data-test="validation-rule-search"
        :label="$t('search_by_column')"
      >
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
      <q-btn-toggle
        v-model="scopeFilter"
        no-caps unelevated
        toggle-color="primary"
        class="list-filter-toggle"
        data-test="scope-filter"
        :options="scopeFilterOptions"
      />
      <q-btn-toggle
        v-model="statusFilter"
        no-caps unelevated
        toggle-color="primary"
        class="list-filter-toggle"
        data-test="status-filter"
        :options="statusFilterOptions"
      />
      <q-space />
      <f-btn color="primary" icon="add" :label="$t('new_rule')" data-test="new-validation-rule" @click="createRule" />
    </div>

    <Loader v-if="loading" />

    <!-- Empty states: nothing configured at all vs. nothing matching. -->
    <div v-else-if="!rules.length" class="rule-empty" data-test="cvr-empty">
      <Icon icon="mdi:shield-check-outline" height="34" width="34" class="rule-empty__icon" />
      <div class="rule-empty__title">{{ $t('no_rules_found') }}</div>
      <div class="rule-empty__hint">{{ $t('custom_validation_rules_description') }}</div>
      <f-btn color="primary" icon="add" :label="$t('new_rule')" class="q-mt-md" @click="createRule" />
    </div>
    <div v-else-if="!filteredRules.length" class="rule-empty" data-test="cvr-no-match">
      {{ $t('no_rules_match') }}
    </div>

    <!-- Rule cards — same card as the transformation-rules list. Clicking a
         card opens the builder; the controls on the right stop propagation. -->
    <div
      v-else
      class="rule-list height-100vh-220px"
      data-test="custom-validation-rules-list"
    >
      <article
        v-for="row in filteredRules"
        :key="row.id"
        class="rule-card"
        :class="{ 'rule-card--off': !row.is_active }"
        :data-test="'validation-rule-' + row.id"
        tabindex="0"
        role="button"
        :aria-label="$t('edit_rule') + ': ' + row.display_name"
        @click="editRule(row)"
        @keydown.enter.prevent="editRule(row)"
        @keydown.space.prevent="editRule(row)"
      >
        <!-- Name, description, badge line -->
        <div class="rule-card__body">
          <div class="item-name">{{ row.display_name }}</div>
          <div v-if="row.description" class="rule-card__desc">{{ row.description }}</div>

          <!-- One line classifies the rule: scope, severity, target, origin. -->
          <div class="rule-card__meta">
            <q-badge :color="scopeBadgeColor(row.scope)" :label="$t(scopeLabelKey(row.scope))" />
            <q-badge
              :color="severityBadgeColor(row.severity)"
              :label="$t(severityLabelKey(row.severity))"
            />
            <q-badge
              v-if="row.target_field"
              color="grey"
              :label="row.target_field"
              data-test="target-field"
            />
            <q-badge
              v-if="row.source"
              :color="sourceBadgeColor(row.source)"
              :label="sourceLabel(row.source)"
            />
            <span v-if="row.log_execution" class="rule-flag" data-test="log-flag">
              <q-icon name="history" size="14px" />
              {{ $t('log_execution') }}
            </span>
          </div>
        </div>

        <!-- Activity, toggle, actions. A system default has no meaningful
             actor, so it shows a dash. -->
        <div class="rule-card__right">
          <div v-if="activityInfo(row)" class="activity">
            <q-avatar class="activity__avatar" size="26px" color="primary" text-color="white">
              {{ activityInfo(row).initials }}
            </q-avatar>
            <div class="activity__text">
              <span class="activity__name">{{ activityInfo(row).name }}</span>
              <span class="activity__date">{{ formatTimeAgo(activityInfo(row).dateIso) }}</span>
            </div>
            <q-tooltip
              v-if="formatTimestamp(activityInfo(row).dateIso)"
              data-test="activity-timestamp"
            >
              {{ formatTimestamp(activityInfo(row).dateIso) }}
            </q-tooltip>
          </div>
          <span v-else class="activity__empty">—</span>

          <span class="rule-card__toggle" @click.stop>
            <f-toggle
              size="xs"
              :model-value="row.is_active"
              :disable="togglingIds.includes(row.id)"
              :data-test="'toggle-validation-rule-' + row.id"
              @update:model-value="(val: boolean) => toggleActive(row, val)"
            />
            <q-spinner v-if="togglingIds.includes(row.id)" size="14px" class="q-ml-xs" />
          </span>

          <RowActionsMenu
            :actions="rowActions"
            :row="row"
            @action="handleRowAction({ action: $event, rowId: row.id, row })"
          />
        </div>
      </article>
    </div>

    <!-- Delete confirmation -->
    <q-dialog v-model="deleteDialog" persistent>
      <q-card style="min-width: 400px;">
        <q-card-section class="bg-primary text-white q-py-sm q-px-md">
          <div class="row items-center">
            <q-icon name="warning" size="xs" color="white" class="q-mr-sm" />
            <div class="text-subtitle1">{{ $t('confirm_delete') }}</div>
          </div>
        </q-card-section>
        <q-card-section class="q-pt-md">
          <p>{{ $t('confirm_delete_validation_rule') }}</p>
        </q-card-section>
        <q-card-actions align="right" class="q-pa-md">
          <f-btn appearance="cancel" data-test="delete-rule-cancel" :label="$t('cancel')" v-close-popup />
          <f-btn
            :label="$t('delete')"
            data-test="delete-rule-confirm"
            v-close-popup
            @click="confirmDelete()"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Reset-to-default confirmation — removes the org override so the
         underlying system default takes over again. -->
    <q-dialog v-model="resetDialog" persistent>
      <q-card style="min-width: 400px;">
        <q-card-section class="bg-primary text-white q-py-sm q-px-md">
          <div class="row items-center">
            <q-icon name="warning" size="xs" color="white" class="q-mr-sm" />
            <div class="text-subtitle1">{{ $t('reset_to_default') }}</div>
          </div>
        </q-card-section>
        <q-card-section class="q-pt-md">
          <p>{{ $t('reset_to_default_confirm') }}</p>
        </q-card-section>
        <q-card-actions align="right" class="q-pa-md">
          <f-btn appearance="cancel" data-test="reset-rule-cancel" :label="$t('cancel')" v-close-popup />
          <f-btn
            :label="$t('reset_to_default')"
            data-test="reset-rule-confirm"
            v-close-popup
            @click="confirmReset()"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { useFormattedTimeAgo, useFormattedTimestamp } from 'src/boot/timeago';
import { customValidationRulesApiService } from 'src/services';
import { useCvrListFiltersStore } from 'src/store/Settings/cvr-list-filters.store';
import type { CvrListFilters } from 'src/store/Settings/cvr-list-filters.store';
import { slugify, isAppliesWhenEmpty } from './rule-builder-model';
import Loader from 'src/components/Loader.vue';
import RowActionsMenu from 'src/components/Table/RowActionsMenu.vue';
import type { RowActionItem, RowActionPayload } from 'src/components/Table/types/table/unified-table';
import type { CustomValidationRule, CustomRuleScope, CustomRuleSeverity, CreateValidationRulePayload } from 'src/services/settings/CustomValidationRulesApiService';

export default defineComponent({
  name: 'CustomValidationRulesList',
  components: {
    Loader,
    RowActionsMenu,
  },
  data() {
    return {
      doc_type_key: '',
      // Free-text search above the table (matches name/description/field/etc.).
      search: '',
      // Scope toggle above the table: 'all' | 'header' | 'line'.
      scopeFilter: 'all' as 'all' | CustomRuleScope,
      // Status toggle: 'all' | 'active' | 'inactive' (filters is_active).
      statusFilter: 'all' as 'all' | 'active' | 'inactive',
      // Actions depend on the rule's origin. A system default offers Customize
      // (fork it into an editable org copy); an org rule offers Edit instead.
      // Duplicate is available for every rule. The last slot is either Reset to
      // Default (org rule overriding a system default) or Delete (from-scratch
      // custom rule); a system default has neither (it cannot be removed).
      rowActions: [
        { key: 'customize', label: 'customize', icon: 'tune', color: 'primary', show: (row: CustomValidationRule) => this.isDefaultRule(row) },
        { key: 'edit', label: 'edit', icon: 'edit', color: 'primary', show: (row: CustomValidationRule) => !this.isDefaultRule(row) },
        { key: 'duplicate', label: 'duplicate', icon: 'content_copy', color: 'primary' },
        { key: 'reset', label: 'reset_to_default', icon: 'restore', color: 'negative', separator: true, show: (row: CustomValidationRule) => row.source === 'customized' },
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true, show: (row: CustomValidationRule) => row.source === 'custom' },
      ] as RowActionItem[],
    };
  },
  computed: {
    scopeFilterOptions(): { label: string; value: 'all' | CustomRuleScope }[] {
      return [
        { label: this.$t('all'), value: 'all' },
        { label: this.$t('scope_header'), value: 'header' },
        { label: this.$t('scope_line'), value: 'line' },
        { label: this.$t('scope_table'), value: 'table' },
      ];
    },
    statusFilterOptions(): { label: string; value: 'all' | 'active' | 'inactive' }[] {
      return [
        { label: this.$t('all'), value: 'all' },
        { label: this.$t('active'), value: 'active' },
        { label: this.$t('inactive'), value: 'inactive' },
      ];
    },
    // Bundle the toolbar filters so a single watcher can persist them.
    filterState(): CvrListFilters {
      return {
        search: this.search,
        scopeFilter: this.scopeFilter,
        statusFilter: this.statusFilter,
      };
    },
    filteredRules(): CustomValidationRule[] {
      const q = this.search.trim().toLowerCase();
      return this.rules.filter((r: CustomValidationRule) => {
        if (this.scopeFilter !== 'all' && r.scope !== this.scopeFilter) {
          return false;
        }
        if (this.statusFilter === 'active' && !r.is_active) {
          return false;
        }
        if (this.statusFilter === 'inactive' && r.is_active) {
          return false;
        }
        if (q && !this.matchesSearch(r, q)) {
          return false;
        }
        return true;
      });
    },
  },
  watch: {
    // Persist the toolbar filters so they survive navigating into a rule and
    // back (and are restored on mount). Keyed to the current doc type.
    filterState: {
      deep: true,
      handler(state: CvrListFilters) {
        this.cvrFilters.setFilters(this.doc_type_key, state);
      },
    },
  },
  mounted() {
    this.doc_type_key = String(this.$route.params.doc_type || '');
    const saved = this.cvrFilters.filtersFor(this.doc_type_key);
    this.search = saved.search;
    this.scopeFilter = saved.scopeFilter;
    this.statusFilter = saved.statusFilter;
    this.loadRules();
  },
  methods: {
    async loadRules() {
      if (!this.doc_type_key) {
        return;
      }
      try {
        this.loading = true;
        const resp = await customValidationRulesApiService.list(this.doc_type_key);
        this.rules = Array.isArray(resp) ? resp : [];
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async toggleActive(row: CustomValidationRule, val: boolean) {
      if (this.togglingIds.includes(row.id)) {
        return;
      }
      const previous = row.is_active;
      // Optimistic update — flip immediately, revert if the call fails.
      row.is_active = val;
      this.togglingIds.push(row.id);
      try {
        await customValidationRulesApiService.setActive(row.id, val);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        row.is_active = previous;
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.togglingIds = this.togglingIds.filter((id) => id !== row.id);
      }
    },
    // Seeded system rules carry source === 'system_default'; badge them.
    isDefaultRule(row: CustomValidationRule): boolean {
      return row.source === 'system_default';
    },
    // Quasar color per rule origin — the global theme tints these into
    // soft pills. Orange = seeded system default, primary = org-authored
    // custom, blue = an overridden system rule, grey = anything else.
    sourceBadgeColor(source: string): string {
      switch (source) {
        case 'system_default':
          return 'orange';
        case 'customized':
          return 'blue';
        case 'custom':
          return 'primary';
        default:
          return 'grey';
      }
    },
    // Default rules are system-managed and cannot be deleted — open confirm.
    onDelete(row: CustomValidationRule) {
      if (this.isDefaultRule(row)) {
        return;
      }
      this.ruleToDelete = row;
      this.deleteDialog = true;
    },
    async confirmDelete() {
      const row = this.ruleToDelete;
      if (!row) {
        return;
      }
      try {
        await customValidationRulesApiService.deleteValidationRule(row.id);
        notify.success(this.$t('MSG_DELETE'));
        this.rules = this.rules.filter((r) => r.id !== row.id);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.ruleToDelete = null;
      }
    },
    // Render the server's `source` as a translated badge label. Known sources
    // map to dedicated i18n keys; anything unexpected falls back to a
    // humanized version of the raw value so it still renders sensibly.
    sourceLabel(source: string): string {
      if (!source) {
        return '';
      }
      const known: Record<string, string> = {
        system_default: 'system_default',
        customized: 'customized',
        custom: 'custom',
      };
      if (known[source]) {
        return this.$t(known[source]);
      }
      return source
        .split('_')
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
    },
    // Free-text search across the columns a user would reasonably search
    // by. `q` is already trimmed + lower-cased by the caller.
    matchesSearch(r: CustomValidationRule, q: string): boolean {
      const haystack = [
        r.display_name,
        r.description,
        r.target_field,
        this.$t(this.scopeLabelKey(r.scope)),
        this.$t(this.severityLabelKey(r.severity)),
        this.sourceLabel(r.source),
      ];
      return haystack.some((v) => (v || '').toLowerCase().includes(q));
    },
    // Severity badge color — matches the mockup: error = red, warning =
    // amber, info = blue (info isn't produced by the current backend).
    severityBadgeColor(severity: CustomRuleSeverity): string {
      const map: Record<CustomRuleSeverity, string> = {
        error: 'negative',
        warning: 'warning',
        info: 'info',
      };
      return map[severity] || 'grey';
    },
    // Initials for the activity avatar — same rule as the header User
    // Dropdown: first + last name initial (single name → one letter).
    getInitials(fullname: string): string {
      const names = (fullname || '').trim().split(/\s+/);
      let initials = names[0].substring(0, 1).toUpperCase();
      if (names.length > 1) {
        initials += names[names.length - 1].substring(0, 1).toUpperCase();
      }
      return initials;
    },
    // The rule's latest audit touch: last-modified if a name is recorded,
    // else created. Seeded system defaults have no meaningful actor, so they
    // show no user — even when the backend stamps one on them.
    activityInfo(
      row: CustomValidationRule,
    ): { name: string; initials: string; dateIso: string } | null {
      if (row.source === 'system_default') {
        return null;
      }
      if (row.last_modified_by_name) {
        return {
          name: row.last_modified_by_name,
          initials: this.getInitials(row.last_modified_by_name),
          dateIso: row.last_modified_on || '',
        };
      }
      if (row.created_by_name) {
        return {
          name: row.created_by_name,
          initials: this.getInitials(row.created_by_name),
          dateIso: row.created_on || '',
        };
      }
      return null;
    },
    // Quasar color per scope — the shadcn theme tints these into soft pills
    // (same pattern as severity). Distinct hues, none clashing with the
    // red/amber severity badges.
    scopeBadgeColor(scope: CustomRuleScope): string {
      const map: Record<CustomRuleScope, string> = {
        header: 'blue',
        line: 'green',
        table: 'mission',
      };
      return map[scope] || 'grey';
    },
    scopeLabelKey(scope: CustomRuleScope): string {
      const map: Record<CustomRuleScope, string> = {
        header: 'scope_header',
        line: 'scope_line',
        table: 'scope_table',
      };
      return map[scope] || scope;
    },
    severityLabelKey(severity: CustomRuleSeverity): string {
      const map: Record<CustomRuleSeverity, string> = {
        error: 'validation_severity_error',
        warning: 'validation_severity_warning',
        info: 'validation_severity_info',
      };
      return map[severity] || severity;
    },
    createRule() {
      this.$router.push('/settings/custom-validation-rules/' + this.doc_type_key + '/new');
    },
    // The row-actions menu hands back only the action key; the card supplies
    // the row, so the payload shape matches the table's old contract.
    handleRowAction(payload: RowActionPayload) {
      const row = payload.row as CustomValidationRule;
      if (payload.action === 'customize') {
        this.customizeRule(row);
      } else if (payload.action === 'edit') {
        this.editRule(row);
      } else if (payload.action === 'duplicate') {
        this.duplicateRule(row);
      } else if (payload.action === 'reset') {
        this.onReset(row);
      } else if (payload.action === 'delete') {
        this.onDelete(row);
      }
    },
    // Customize a system-default rule: ask the backend for an editable org copy
    // (a new rule with the same rule_key), then open it in the builder. The
    // returned rule is handed over via router state so the builder prefills it
    // without a refetch. The system default disappears from the list once the
    // override exists — reversible via Reset to Default.
    async customizeRule(row: CustomValidationRule) {
      if (!row || !row.id) {
        return;
      }
      try {
        const override = await customValidationRulesApiService.customize(row.id);
        this.$router.push({
          path: '/settings/custom-validation-rules/' + this.doc_type_key + '/' + override.id,
          state: { rule: JSON.parse(JSON.stringify(override)) },
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    // Reset a customized rule back to its system default. This deletes the org
    // override; the backend then re-exposes the underlying system default.
    onReset(row: CustomValidationRule) {
      this.ruleToReset = row;
      this.resetDialog = true;
    },
    async confirmReset() {
      const row = this.ruleToReset;
      if (!row) {
        return;
      }
      try {
        await customValidationRulesApiService.deleteValidationRule(row.id);
        notify.success(this.$t('reset_to_default_success'));
        await this.loadRules();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.ruleToReset = null;
      }
    },
    // Duplicate a rule: copy its full definition into a brand-new rule with
    // " - Copy" appended to the name (and a matching fresh rule_key). Works
    // for system-default rules too — the copy is created as a custom rule.
    async duplicateRule(row: CustomValidationRule) {
      const display_name = `${row.display_name} - Copy`;
      const payload: CreateValidationRulePayload = {
        doc_type: this.doc_type_key,
        scope: row.scope,
        rule_key: slugify(display_name),
        display_name,
        description: row.description,
        target_field: row.target_field,
        assertion: row.assertion,
        error_code: row.error_code,
        error_message: row.error_message,
        severity: row.severity,
        priority: row.priority,
        is_active: row.is_active,
        log_execution: row.log_execution,
      };
      // Omit applies_when when the source has no conditions (an empty
      // { all: [] } must not be sent — see assembleApiCore).
      if (row.applies_when && !isAppliesWhenEmpty(row.applies_when)) {
        payload.applies_when = row.applies_when;
      }
      try {
        await customValidationRulesApiService.create(payload);
        notify.success(this.$t('MSG_SAVE'));
        await this.loadRules();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    editRule(row: CustomValidationRule) {
      if (!row || !row.id) {
        return;
      }
      // Hand the full row to the builder via router state so edit mode
      // prefills without an extra fetch (falls back to list-by-id on refresh).
      this.$router.push({
        path: '/settings/custom-validation-rules/' + this.doc_type_key + '/' + row.id,
        state: { rule: JSON.parse(JSON.stringify(row)) },
      });
    },
  },
  setup() {
    return {
      cvrFilters: useCvrListFiltersStore(),
      formatTimeAgo: useFormattedTimeAgo,
      formatTimestamp: useFormattedTimestamp,
      rules: ref([] as CustomValidationRule[]),
      loading: ref(false),
      togglingIds: ref([] as string[]),
      deleteDialog: ref(false),
      ruleToDelete: ref<CustomValidationRule | null>(null),
      resetDialog: ref(false),
      ruleToReset: ref<CustomValidationRule | null>(null),
    };
  },
});
</script>

<style scoped lang="scss">
// Entirely shared blocks (.page-head, .page-intro, .rule-list, .rule-card,
// .item-name, .activity) from shadcn-theme.scss — nothing screen-specific.
</style>
